  const w2y = Math.cos(y*0.03+t*0.45)*8 + Math.sin(x*0.028-t*0.55)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.7+3)*60,40+Math.cos(t*0.3+1)*40,0.14,2.1],
    [400+Math.cos(t*0.45+2)*70,200+Math.sin(t*0.65+4)*50,0.11,1.8],
    [200+Math.sin(t*0.55+6)*110,220+Math.cos(t*0.75)*60,0.05,2.8],
    [300+Math.cos(t*0.85)*50,30+Math.sin(t*0.5+5)*45,0.13,1.4]
  ];
  let aS=0,iS=0,mS=0;
  for(let k=0;k<src.length;k++){
    const[sX,sY,f,sp]=src[k],d=Math.sqrt((sx-sX)**2+(sy-sY)**2),w=1+0.3*Math.sin(k*1.7);
    aS+=Math.sin(d*f-t*sp)*w;iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;mS+=Math.sin(d*f*1.3-t*sp*0.4+3)*w;
  }
  const act=aS/10,inh=iS/10,mod=mS/10;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.06*Math.sin(t*0.15)+t*0.6)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.08-ang*2+t*0.9)*0.2+Math.sin(dist*0.03+ang*6-t*2)*0.15;
  const pulse=Math.sin(dist*0.1-t*3)*Math.exp(-dist*0.005)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+mod*0.4+pulse)*2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-sy*0.08+t*0.7)*0.3)*1.5)*0.25;
  const micro=Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const v=(reaction*0.6+cell*0.25+micro)*0.5+0.5;
  const pal=[[5,10,45],[10,45,85],[15,85,120],[20,140,135],[80,180,120],[180,195,60],[220,175,50],[215,120,55],[190,65,60],[140,40,75],[85,25,65],[40,15,55],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15,edge=Math.abs(reaction)>0.65?1.12:1,glow=Math.max(0,reaction-0.5)*0.3;
  return[Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*60)|0),Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*40)|0),Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*30)|0)];
}
